/**
 * GLSL fragment shaders for Custom Effects: `env.shader(source, uniforms)` inside render(ctx, env).
 *
 * One offscreen WebGL canvas is shared by every effect. The shader runs over the layer at its
 * on-screen pixel size and the result is drawn into the layer (already clipped to its shape).
 *
 * Two source styles work:
 *  - The Book of Shaders style: `void main()` with `uniform vec2 u_resolution; uniform float u_time;
 *    uniform vec2 u_mouse;` (u_mouse in pixels, origin bottom-left).
 *  - Shadertoy style: `void mainImage(out vec4 fragColor, in vec2 fragCoord)` with iResolution,
 *    iTime and iMouse provided automatically.
 * Extra uniforms come from the second argument: numbers -> float, [x, y(, z, w)] -> vecN,
 * '#rrggbb' -> vec3.
 *
 * The same file is copied into every runtime package (packages/{name}/src/glShader.ts) so the
 * editor and published runtimes draw identically.
 */
/** Wrap a user source into a complete GLSL ES 1.0 fragment shader. */
export declare function wrapFragmentSource(source: string): string;
/**
 * Run `source` over a w x h layer centred on the current origin and draw it into ctx.
 * `mouse` is the pointer in layer pixels from the top-left, or null.
 * Throws the GLSL error log when the shader does not compile (the effect editor shows it).
 */
export declare function drawShader(ctx: CanvasRenderingContext2D, w: number, h: number, source: string, uniforms?: Record<string, any>, mouse?: {
    x: number;
    y: number;
    down?: boolean;
} | null): void;
